@startuml

class Employee {
  + idNumber : string
  + name : string
  + address : string
}

class AssemblyService {
  + kmsAtTime : int
  + workHours : float
  + admissionDate : date
  + finishDate : date
}

class PartAccessory {
  + category : string
  + serialNumber : string
  + price : double
}

class Car {
  + licensePlate : string
  + make : string
  + model : string
  + color : string
}

class Owner {
  + idNumber : string
  + name : string
  + address : string
  + phone : string
}

class CarModel {}

Employee "1" -- "*" AssemblyService : responsible_for
Car "1" -- "*" AssemblyService : subject_of
AssemblyService "*" -- "*" PartAccessory : fits
PartAccessory "*" -- "*" CarModel : fits_in

Owner "1" -- "1..*" Car : owns
Car "1" -- "*" AssemblyService : undergoes

@enduml

